prompt --application/shared_components/plugins/template_component/amc_next_calendar
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(380644286404402539)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_CALENDAR'
,p_display_name=>'Next Calendar'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<time class="amc-NCalendar-when" datetime="#START_DATE#">{if ?DATE_LABEL/}#DATE_LABEL#{else/}#START_DATE#{endif/}</time>',
'<div class="amc-NCalendar-what">',
'  <h3 class="amc-NCalendar-title">{if ?LINK_URL/}<a class="amc-NCalendar-link" href="#LINK_URL#">#TITLE#</a>{else/}#TITLE#{endif/}</h3>',
'  {if ?DESCRIPTION/}<p class="amc-NCalendar-desc">#DESCRIPTION#</p>{endif/}',
'  <p class="amc-NCalendar-meta">{if ?CATEGORY/}<span class="amc-NCalendar-cat">#CATEGORY#</span>{endif/}<span class="amc-NCalendar-state">{case STATE/}{when success/}Confirmed{when warning/}Attention{when danger/}Critical{when info/}Info{otherwise/}Scheduled{endcase/}</span></p>',
'</div>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NCalendar amc-NCalendar--#STYLE#" data-view="#STYLE#" data-first-day="#FIRST_DAY#" data-initial-date="#INITIAL_DATE#" data-calendar="#CALENDAR_SYSTEM#" data-day-start="#DAY_START#" data-day-end="#DAY_END#" data-zoom="#LANE_ZOOM#" data-count="#UPCOMING_COUNT#">',
'  <span class="amc-NCalendar-i18n" hidden data-prev="Previous" data-next="Next" data-more="more" data-all-day="All day" data-close="Close" data-no-events="No events" data-none-upcoming="No upcoming events" data-now="Happening now" data-day="Day" data-week="Week" data-month="Month" data-legend-low="Less" data-legend-high="More" data-other="Other" data-event-one="event" data-event-other="events" data-next-up="Next up" data-starts-in="Starts in" data-zoom="Zoom" data-total="Total" data-busiest="Busiest day" data-next-event="Next"></span>',
'  <ol class="amc-NCalendar-source">#APEX$ROWS#</ol>',
'</div>'))
,p_report_row_template=>'<li class="amc-NCalendar-event amc-NCalendar-event--{case STATE/}{when success/}success{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/}" data-start="#START_DATE#" data-end="#END_DATE#" data-category="#CATEGORY!ATTR#" data-all-day="#ALL_DAY#" data-value="#VALUE#" data-state="{case STATE/}{when success/}success{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/}">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-calendar.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-calendar.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'One query row per event. Map Start Date (required) and Title (required); return dates as text in ISO form with TO_CHAR(date_col, ''YYYY-MM-DD"T"HH24:MI''), or ''YYYY-MM-DD'' for all-day events. End Date is exclusive for timed events and the last day for all-day events. Category groups events by color and makes the lanes of Timeline Lanes. State accepts success, warning, danger, info or neutral. Value is a number that drives the Heatmap intensity instead of the event count. Without JavaScript the rows show as a readable agenda list; the runtime file builds the chosen view, keyboard navigation and live updates, and rebuilds after a region refresh.'
,p_version_identifier=>'1.0.1'
,p_files_version=>2
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(400400274450864135)
,p_plugin_id=>wwv_flow_imp.id(380644286404402539)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'month'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Calendar view; the direction is given in brackets as motion, depth, bold or smart. month [smart]: month grid with event chips, a +N more popover and a today ring; in narrow regions it becomes a dot calendar with the selected day''s agenda. agenda [smart]: events grouped by day under sticky day headers with Today and Tomorrow labels and durations; the date moves beside the events in wide regions. week [depth]: seven day columns on an hour grid, events placed by time, overlapping events side by side, all-day row and a live now line. heatmap [bold]: a year of days colored by the number of events, or by the sum of Value, with month labels, legend, busiest day and day tooltips. timelineLanes [smart]: a resource schedule with one lane per Category on a time scale that zooms between day, week and month. posterDay [bold]: a giant date poster for today or the Initial Date with that day''s events beside it, for home pages and kiosks. flipDate [depth]: a desk tear-off calendar whose page flips in 3D to the next or previous day, with the day''s events written on the page. countdown [motion]: live tiles counting down days, hours and minutes to the next events, updated every minute. circularYear [bold]: the year as a ring of month arcs with events as dots; selecting a month lists its events in the centre. miniDots [motion]: a compact mini calendar with category dots, a sliding selection and a smooth reveal of the selected day''s events, for sidebars.'
);
